        scenario = load_scenario(
            settings.scenarios_path() / f"{key}.yaml", settings
        ).scenario
        assert [
            (blocker.barrier_id, blocker.station, blocker.scenario_id)
            for blocker in scenario.blocked_by
        ] == declarations"},{"id":"C2","fichier":"scenario.js","ligne":1,"severite":"Nit","description":"Le diff ne contient aucun changement côté front, alors que la story exige `blockersBlock` dans `scenario.js` pour rendre l’encart après la correction et avant « Recommencer ». Le panneau serveur peut donc fournir `blockers` sans que l’interface l’affiche." ,"test_pytest":null}]}
